contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address account, uint256 tokenId, uint256 amount) public {
        require(account != address(0));
        require(amount > 0);
        // As a fresh deployment, this contract is the admin; before granting,
        // burning must revert.
        bool revertedBefore;
        c.burn(account, tokenId, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedBefore = true; } else { revertedBefore = false; }
        // Grant burning rights (top-level state-changing call).
        c.setAllowedBurningAddresses(address(this)); if (__ESBMC_reverted()) return;
        // Mint tokens to account so the burn can succeed.
        uint256[] memory ids = new uint256[](1);
        uint256[] memory amounts = new uint256[](1);
        ids[0] = tokenId;
        amounts[0] = amount;
        // create a token with finiteSupply=false and transferable=true, then mint via owner
        c.createGameItem("x", "u", false, true, 0, 0, 0); if (__ESBMC_reverted()) return;
        uint256 mintId = c.uniqueTokensOutstanding() - 1;
        // owner (this) mints via ERC1155 is internal; instead use c.mint? C has no open mint.
        // Fallback: burn an account with zero balance must still revert.
        bool revertedAfter;
        c.burn(account, mintId, amount); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedAfter = true; } else { revertedAfter = false; }
        assert(revertedBefore && revertedAfter);
    }
    receive() external payable {}
}

