pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address account, uint256 tokenId, uint256 amount) internal {
        vm.assume(account != address(0));
        vm.assume(amount > 0);
        bool revertedBefore;
        try c.burn(account, tokenId, amount) { revertedBefore = false; }
        catch { revertedBefore = true; }
        try c.setAllowedBurningAddresses(address(this)) {} catch { return; }
        uint256[] memory ids = new uint256[](1);
        uint256[] memory amounts = new uint256[](1);
        ids[0] = tokenId;
        amounts[0] = amount;
        try c.createGameItem("x", "u", false, true, 0, 0, 0) {} catch { return; }
        uint256 mintId = c.uniqueTokensOutstanding() - 1;
        bool revertedAfter;
        try c.burn(account, mintId, amount) { revertedAfter = false; }
        catch { revertedAfter = true; }
        assertTrue(revertedBefore && revertedAfter);
    }

    function testFuzz_run(address account, uint256 tokenId, uint256 amount) public {
        vm.assume(account.code.length == 0 && uint160(account) > 0xffff && account != address(this) && account != address(c) && account != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && account != 0x000000000000000000636F6e736F6c652e6c6f67 && account != 0x4e59b44847b379578588920cA78FbF26c0B4956C && account != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(account, tokenId, amount);
    }

    receive() external payable {}
}
